R.zalias:
protected static function zalias( $o ) {
	// Meta gali grįžti ir masyvu (WC kartais deserializuoja pati) — tada
	// (string) cast'as kėlė „Array to string conversion" (H240).
	$m = $o->get_meta( self::META );
	if ( is_array( $m ) ) { return $m; }
	$s = json_decode( (string) $m, true );
	return is_array( $s ) ? $s : array();
}

R.prideti:
public static function prideti_is_plugino( $order_id, $sandelis, $manifesto_kodas ) {
	$o = wc_get_order( $order_id );
	if ( ! $o ) { return false; }

	$raw = $o->get_meta( 'venipak_shipping_order_data' );
	$d   = is_array( $raw ) ? $raw : json_decode( (string) $raw, true );
	if ( empty( $d['pack_numbers'] ) || ! is_array( $d['pack_numbers'] ) ) { return false; }

	$sarasas = self::zalias( $o );
	$sarasas[ sanitize_key( $sandelis ) ] = array(
		'sandelis'  => sanitize_key( $sandelis ),
		'kodas'     => sanitize_text_field( $manifesto_kodas ),
		'manifest'  => sanitize_text_field( $d['manifest'] ?? '' ),
		'numeriai'  => array_map( 'sanitize_text_field', $d['pack_numbers'] ),
		'data'      => current_time( 'mysql' ),
	);
	$o->update_meta_data( self::META, wp_json_encode( $sarasas ) );
	$o->add_order_note( sprintf( 'Siuntos numeriai išsaugoti (%s): %s',
		mb_strtoupper( $sandelis ), implode( ', ', $d['pack_numbers'] ) ), false, true );
	$o->save();
	/* E1b (Q-E0-1): vienintelis pranesimas is sio failo. Logika NESIKEICIA.
	   `prideti_is_plugino()` yra Venipak-only, todel vezejas cia visada
	   'venipak'; LP Express siuntos faktus gauna per naktini cron. */
	do_action( 'petshop_siunta_sukurta', (int) $order_id, sanitize_key( $sandelis ), 'venipak', (array) $d['pack_numbers'] );
	return true;
}

R.registruota_grupiu:
public static function registruota_grupiu( $o ) {
	return count( self::zalias( $o ) );
}

R.likutis_dl:
protected static function likutis( $pid, $delta, $pastaba ) {
	$pid = (int) $pid;
	if ( class_exists( 'Petshop_AV_Stock' ) && null !== Petshop_AV_Stock::qty( $pid ) ) {
		return $delta > 0 ? Petshop_AV_Stock::increase( $pid, $delta, $pastaba ) : Petshop_AV_Stock::decrease( $pid, -$delta, $pastaba );
	}
	$p = wc_get_product( $pid );
	if ( ! $p ) { return new WP_Error( 'nera', 'prekės nėra' ); }
	$dabar = (int) get_post_meta( $pid, '_stock', true );
	if ( $dabar + $delta < 0 ) { return new WP_Error( 'nepakanka', 'AV tik ' . $dabar ); }
	if ( ! $p->managing_stock() ) { return $dabar + $delta; }
	$naujas = wc_update_product_stock( $p, abs( $delta ), $delta > 0 ? 'increase' : 'decrease' ); // atominis SQL (auditas V2)
	return null === $naujas ? new WP_Error( 'klaida', 'likučio įrašyti nepavyko' ) : (int) $naujas;
}
